require_once __DIR__.'/_common.php';$current_slug='data-anak';require_once ROOT_PATH.'/includes/auth-guard.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$anak=$id?data_anak_get($id):null;if(!$anak){set_flash('warning','Data anak tidak ditemukan.');redirect(data_anak_url());}
$s=$pdo->prepare('SELECT pg.*,u.nama AS nama_petugas,sg.zscore_bb_u,sg.zscore_tb_u,sg.status_bb_u,sg.status_tb_u FROM pengukuran pg LEFT JOIN user u ON u.id_user=pg.id_user LEFT JOIN status_gizi sg ON sg.id_pengukuran=pg.id_pengukuran WHERE pg.id_anak=? ORDER BY pg.tanggal_pengukuran');$s->execute([$id]);$riwayat=$s->fetchAll();$page_title='Detail Anak';$flash=get_flash();
$plot=function($key,$label,$color)use($riwayat){$vals=array_values(array_filter(array_map(fn($r)=>$r[$key]===null?null:(float)$r[$key],$riwayat),fn($v)=>$v!==null));if(count($vals)<2)return ''; $min=min($vals);$max=max($vals);$range=max($max-$min,0.01);$points=[];foreach($riwayat as $i=>$r){if($r[$key]!==null)$points[]=sprintf('%.1f,%.1f',20+$i*260/max(count($riwayat)-1,1),180-((float)$r[$key]-$min)/$range*150);}return '<svg viewBox="0 0 280 200" role="img" aria-label="Grafik '.$label.'"><polyline fill="none" stroke="'.$color.'" stroke-width="3" points="'.implode(' ',$points).'"/>'.implode('',array_map(fn($p)=>'<circle cx="'.explode(',',$p)[0].'" cy="'.explode(',',$p)[1].'" r="4" fill="'.$color.'"/>',$points)).'</svg>';};
require ROOT_PATH.'/includes/header.php'; ?>
