<?php if($flash): ?><div class="alert alert-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<div class="row g-4 mb-4"><div class="col-lg-6"><div class="card h-100"><div class="card-header"><h5 class="mb-0">Profil Anak</h5></div><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">NIK</dt><dd class="col-sm-8"><?= e($anak['nik']) ?></dd><dt class="col-sm-4">Tanggal lahir</dt><dd class="col-sm-8"><?= date('d F Y',strtotime($anak['tanggal_lahir'])) ?></dd><dt class="col-sm-4">Jenis kelamin</dt><dd class="col-sm-8"><?= $anak['jenis_kelamin']==='L'?'Laki-laki':'Perempuan' ?></dd><dt class="col-sm-4">Posyandu</dt><dd class="col-sm-8"><?= e($anak['nama_posyandu']) ?></dd><dt class="col-sm-4">Alamat</dt><dd class="col-sm-8"><?= nl2br(e($anak['alamat']?:'-')) ?></dd></dl></div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-header"><h5 class="mb-0">Orang Tua / Wali</h5></div><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">Nama ayah</dt><dd class="col-sm-8"><?= e($anak['nama_ayah']?:'-') ?></dd><dt class="col-sm-4">Nama ibu</dt><dd class="col-sm-8"><?= e($anak['nama_ibu']?:'-') ?></dd><dt class="col-sm-4">Telepon</dt><dd class="col-sm-8"><?= e($anak['telepon_wali']?:'-') ?></dd><dt class="col-sm-4">Alamat</dt><dd class="col-sm-8"><?= nl2br(e($anak['alamat_wali']?:'-')) ?></dd></dl></div></div></div></div>
<div class="row g-4 mb-4"><div class="col-lg-6"><div class="card"><div class="card-header"><h5 class="mb-0">Grafik Tinggi Badan (TB/U)</h5></div><div class="card-body text-center"><?= $plot('tinggi_badan','tinggi badan','#2878c8')?:'<p class="text-muted mb-0">Grafik tersedia setelah ada minimal dua pengukuran tinggi.</p>' ?><small class="text-muted">Nilai tinggi badan (cm) mengikuti urutan tanggal pengukuran.</small></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header"><h5 class="mb-0">Grafik Berat Badan (BB/U)</h5></div><div class="card-body text-center"><?= $plot('berat_badan','berat badan','#20a477')?:'<p class="text-muted mb-0">Grafik tersedia setelah ada minimal dua pengukuran berat.</p>' ?><small class="text-muted">Nilai berat badan (kg) mengikuti urutan tanggal pengukuran.</small></div></div></div></div>
<div class="card"><div class="card-header"><h5 class="mb-0">Riwayat Pengukuran (<?= count($riwayat) ?>)</h5></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Tanggal</th><th>BB (kg)</th><th>TB (cm)</th><th>Z-score BB/U</th><th>Status BB/U</th><th>Z-score TB/U</th><th>Status TB/U</th><th>Petugas</th></tr></thead><tbody><?php if(!$riwayat): ?><tr><td colspan="8" class="text-center text-muted py-4">Belum ada riwayat pengukuran.</td></tr><?php endif;foreach(array_reverse($riwayat) as $r): ?><tr><td><?= date('d/m/Y',strtotime($r['tanggal_pengukuran'])) ?></td><td><?= e($r['berat_badan']??'-') ?></td><td><?= e($r['tinggi_badan']??'-') ?></td><td><?= e($r['zscore_bb_u']??'-') ?></td><td><?= e($r['status_bb_u']??'-') ?></td><td><?= e($r['zscore_tb_u']??'-') ?></td><td><?= e($r['status_tb_u']??'-') ?></td><td><?= e($r['nama_petugas']??'-') ?></td></tr><?php endforeach; ?></tbody></table></div></div>
